import math


def pka_from_ka(ka: float) -> float:
    return -math.log10(ka)


def ph_from_ratio(pka: float, base: float, acid: float) -> float:
    """pH given pKa and [base], [acid]."""
    if acid <= 0 or base <= 0:
        raise ValueError("acid and base concentrations must be positive")
    return pka + math.log10(base / acid)


def ratio_from_ph(pka: float, target_ph: float) -> float:
    """Required [base]/[acid] ratio to hit a target pH."""
    return 10.0 ** (target_ph - pka)


def split_from_ph(pka: float, target_ph: float, total: float):
    """Required (acid, base) concentrations for a target pH at fixed total."""
    r = ratio_from_ph(pka, target_ph)
    base = total * r / (1.0 + r)
    acid = total - base
    return acid, base
